{
   "title": "Instrument",
   "description": "Dataclass containing information about an instrument.",
   "type": "object",
   "properties": {
      "symbol": {
         "title": "Symbol",
         "type": "string"
      },
      "instrument-type": {
         "$ref": "#/$defs/InstrumentType"
      },
      "instrument-key": {
         "$ref": "#/$defs/InstrumentKey"
      },
      "underlying-instrument": {
         "title": "Underlying-Instrument",
         "type": "string"
      },
      "root-symbol": {
         "title": "Root-Symbol",
         "type": "string"
      },
      "exchange": {
         "$ref": "#/$defs/ExchangeType"
      }
   },
   "$defs": {
      "ExchangeType": {
         "description": "Contains the valid exchanges to fetch data for.",
         "enum": [
            "CME",
            "CFE",
            "Equity",
            "Smalls",
            "CBOED",
            "Bond",
            "Cryptocurrency",
            "Equity Offering",
            "Unknown"
         ],
         "title": "ExchangeType",
         "type": "string"
      },
      "InstrumentKey": {
         "description": "Dataclass containing an instrument key.",
         "properties": {
            "symbol": {
               "title": "Symbol",
               "type": "string"
            },
            "instrument-type": {
               "$ref": "#/$defs/InstrumentType"
            }
         },
         "required": [
            "symbol",
            "instrument-type"
         ],
         "title": "InstrumentKey",
         "type": "object"
      },
      "InstrumentType": {
         "description": "This is an :class:`~enum.Enum` that contains the valid types of instruments\nand their representation in the API.",
         "enum": [
            "Bond",
            "Cryptocurrency",
            "Currency Pair",
            "Equity",
            "Equity Offering",
            "Equity Option",
            "Fixed Income Security",
            "Future",
            "Future Option",
            "Index",
            "Liquidity Pool",
            "Unknown",
            "Warrant"
         ],
         "title": "InstrumentType",
         "type": "string"
      }
   },
   "required": [
      "symbol",
      "instrument-type",
      "instrument-key",
      "underlying-instrument",
      "root-symbol",
      "exchange"
   ]
}

